function zoneLesson(i,k){
 const c=C[i],z=T[c.id][k],g=G[k],words=[[z[3],z[4],z[5]],g[2],g[3]];
 let p=ov.querySelector('.wp');if(p)p.remove();p=document.createElement('div');p.className='wp';ov.querySelector('.wm').appendChild(p);
 p.innerHTML=`<div style="display:flex;align-items:center;gap:10px"><span style="font-size:36px">${g[0]}</span><div style="flex:1"><div class="z">${z[0]}</div><div>${z[1]} · ${z[2]}</div></div><button id="zs">🔊</button><button id="zx">✕</button></div>
 <div class="g" style="grid-template-columns:repeat(3,minmax(0,1fr))">${words.map(w=>`<div><b style="font-size:20px">${w[0]}</b><small>${w[1]}</small>${w[2]}</div>`).join('')}</div>
 <button id="zq" style="width:100%;background:#ffd36b">🎯 Thử thách 3 câu để mở khóa khu này</button>`;
 p.querySelector('#zx').onclick=()=>p.remove();p.querySelector('#zs').onclick=()=>say(z[0]+'。'+words.map(w=>w[0]).join('。'));
 p.querySelector('#zq').onclick=()=>{
  const pool=[].concat(...T[c.id].map(t=>[t[3]+' '+t[4]])).concat(G.map(q=>q[2][0]+' '+q[2][1]));
  const Q=words.map(w=>{const right=w[0]+' '+w[1];const o=shuf([...new Set(pool)].filter(x=>x!==right)).slice(0,3);return{ask:'“'+w[2]+'” nói thế nào?',right,opts:shuf([right,...o])}});
  let n=0,ok=0;const show=()=>{if(n>=Q.length){if(ok>=2){tp[c.id]=tp[c.id]||{};tp[c.id][k]=1;save2();if(tdone(c.id)===12){prog[c.id]=3;save()}}
   p.innerHTML=`<div class="z">${ok>=2?'🎉 Mở khóa '+z[0]+'!':'Thử lại nhé'}</div><p>Đúng ${ok}/3 câu.${tdone(c.id)===12?' <b>Bạn đã khám phá đủ 12 khu của '+c.vi+'! Hộ chiếu được đóng dấu.</b>':''}</p><button id="zb">Về bản đồ khu</button>`;p.querySelector('#zb').onclick=()=>town(i);return}
   const q=Q[n];p.innerHTML=`<div>Câu ${n+1}/3</div><div class="z" style="font-size:20px;margin:6px 0">${q.ask}</div>${q.opts.map((o,j)=>`<button class="op" data-j="${j}">${o}</button>`).join('')}`;
   p.querySelectorAll('.op').forEach(b=>b.onclick=()=>{const good=q.opts[+b.dataset.j]===q.right;b.classList.add(good?'ok':'no');if(good){ok++;say(q.right.split(' ')[0])}else p.querySelectorAll('.op').forEach(x=>{if(q.opts[+x.dataset.j]===q.right)x.classList.add('ok')});p.querySelectorAll('.op').forEach(x=>x.onclick=null);setTimeout(()=>{n++;show()},900)})};show()}}

